<script setup>
const route=useRoute();const router=useRouter()
const query=computed(()=>({path:route.path,...route.query}))
const {data:d}=await useFetch('/api/page',{query})
useHead(()=>({title:d.value?.kind==='home'?'Pokédex':`${d.value?.title||'Not found'} – Pokédex`}))
const human=s=>s?.split('-').map(x=>x[0]?.toUpperCase()+x.slice(1)).join(' ')
const search=ref(String(route.query.q||''))
watch(()=>route.query.q,v=>{search.value=String(v||'')})
function filter(key,value){const q={...route.query,[key]:value};delete q.page; if(!value)delete q[key];router.replace({path:route.path,query:q,hash:route.hash})}
function pageLink(n){const q={...route.query};if(n===1)delete q.page;else q.page=String(n);return {path:'/',query:q}}
const methods=computed(()=>[...new Set(d.value?.rows?.map(r=>r.method)||[])].sort((a,b)=>{const order=['level-up','machine','egg','tutor'];return (order.includes(a)?order.indexOf(a):4)-(order.includes(b)?order.indexOf(b):4)||a.localeCompare(b)}))
const relations=[['Super effective against','double_damage_to'],['Not very effective against','half_damage_to'],['No effect against','no_damage_to'],['Weak to','double_damage_from'],['Resists','half_damage_from'],['Immune to','no_damage_from']]
const stats=['HP','Attack','Defense','Sp. Atk','Sp. Def','Speed']
onMounted(()=>{if(route.hash)setTimeout(()=>document.getElementById(route.hash.slice(1))?.scrollIntoView(),100)})
</script>
<template><main v-if="d">
<template v-if="d.kind==='pokemon'">
<div class="summary"><img class="artwork" :src="d.pokemon.sprites.other['official-artwork'].front_default" :alt="d.title"><div><p class="dex">#{{String(d.id).padStart(4,'0')}}</p><h1>{{d.title}}</h1><p class="muted genus">{{d.genus}}</p><div class="badges"><TypeBadge v-for="t in d.pokemon.types" :key="t.slot" :name="t.type.name" link/></div><dl class="measurements"><div><dt>Height</dt><dd>{{(d.pokemon.height/10).toFixed(1)}} m</dd></div><div><dt>Weight</dt><dd>{{(d.pokemon.weight/10).toFixed(1)}} kg</dd></div></dl><p>{{d.flavor}}</p></div></div>
<section aria-labelledby="stats-heading"><h2 id="stats-heading">Base stats</h2><table class="stats"><tbody><tr v-for="(stat,i) in d.pokemon.stats" :key="stat.stat.name"><th scope="row">{{stats[i]}}</th><td>{{stat.base_stat}}</td><td class="bar-cell"><div class="track"><div :style="{width:`${stat.base_stat/255*100}%`}"/></div></td></tr><tr><th scope="row">Total</th><td>{{d.pokemon.stats.reduce((sum,s)=>sum+s.base_stat,0)}}</td><td><div class="track"><div :style="{width:`${d.pokemon.stats.reduce((sum,s)=>sum+s.base_stat,0)/1530*100}%`}"/></div></td></tr></tbody></table></section>
<section aria-labelledby="abilities-heading"><h2 id="abilities-heading">Abilities</h2><ul><li v-for="a in d.pokemon.abilities" :key="a.slot"><a :href="`/abilities/${a.ability.name}`">{{human(a.ability.name)}}</a><span v-if="a.is_hidden"> (hidden)</span></li></ul></section>
<section aria-labelledby="evolution-heading"><h2 id="evolution-heading">Evolution</h2><EvolutionTree :node="d.chain"/></section>
<section id="moves" aria-labelledby="moves-heading"><h2 id="moves-heading">Moves</h2><div class="game-control"><label for="game">Game</label><select id="game" :value="d.game" @change="filter('game',$event.target.value)"><option v-for="g in d.games" :key="g" :value="g">{{human(g)}}</option></select></div><MoveTable v-for="m in methods" :key="d.game+m" :method="m" :rows="d.rows.filter(r=>r.method===m)"/></section>
</template>
<template v-else><h1>{{d.title}}</h1>
<template v-if="d.kind==='home'"><div class="filters"><div><label for="search">Search</label><input id="search" v-model="search" type="search" @input="filter('q',$event.target.value)"></div><div><label for="type">Type</label><select id="type" :value="route.query.type||''" @change="filter('type',$event.target.value)"><option value="">All types</option><option v-for="t in d.types" :key="t.name" :value="t.name">{{t.label}}</option></select></div><div><label for="generation">Generation</label><select id="generation" :value="route.query.generation||''" @change="filter('generation',$event.target.value)"><option value="">All generations</option><option v-for="g in d.generations" :key="g.name" :value="g.name">{{g.label}}</option></select></div></div><p class="muted">{{d.count}} Pokémon</p><PokemonCards v-if="d.cards.length" :cards="d.cards"/><p v-else>No Pokémon found</p><div class="pagination"><NuxtLink v-if="d.page>1" :to="pageLink(d.page-1)">Previous page</NuxtLink><span>Page {{d.page}} of {{d.pages}}</span><NuxtLink v-if="d.page<d.pages" :to="pageLink(d.page+1)">Next page</NuxtLink></div></template>
<template v-else-if="d.kind==='types'&&!d.resource"><ul class="type-list"><li v-for="t in d.types" :key="t.name"><TypeBadge :name="t.name" link/></li></ul></template>
<template v-else-if="d.kind==='moves'"><dl class="details"><div><dt>Type</dt><dd><TypeBadge :name="d.resource.type.name" link/></dd></div><div v-for="[label,value] in [['Category',human(d.resource.damage_class.name)],['Power',d.resource.power],['Accuracy',d.resource.accuracy],['PP',d.resource.pp]]" :key="label"><dt>{{label}}</dt><dd>{{value??'—'}}</dd></div></dl><section aria-labelledby="effect-heading"><h2 id="effect-heading">Effect</h2><p>{{d.effect}}</p></section><section aria-labelledby="learned-heading"><h2 id="learned-heading">Learned by</h2><p class="muted">{{d.cards.length}} Pokémon</p><PokemonCards :cards="d.cards"/></section></template>
<template v-else-if="d.kind==='abilities'"><section aria-labelledby="effect-heading"><h2 id="effect-heading">Effect</h2><p>{{d.effect}}</p></section><section aria-labelledby="pokemon-heading"><h2 id="pokemon-heading">Pokémon</h2><p class="muted">{{d.cards.length}} Pokémon</p><PokemonCards :cards="d.cards"/></section></template>
<template v-else-if="d.kind==='types' || d.kind==='type'"></template>
<template v-else-if="d.kind==='missing'"><p><a href="/">Back to Pokémon</a></p></template>
</template>
<template v-if="d.kind==='types'&&d.resource"><section aria-labelledby="damage-heading"><h2 id="damage-heading">Damage relations</h2><dl class="relations"><div v-for="[label,key] in relations" :key="key"><dt>{{label}}</dt><dd><template v-if="d.resource.damage_relations[key].length"><TypeBadge v-for="t in d.resource.damage_relations[key]" :key="t.name" :name="t.name" link/></template><span v-else>None</span></dd></div></dl></section><section aria-labelledby="pokemon-heading"><h2 id="pokemon-heading">Pokémon</h2><p class="muted">{{d.cards.length}} Pokémon</p><PokemonCards :cards="d.cards"/></section><section aria-labelledby="type-moves-heading"><h2 id="type-moves-heading">Moves</h2><p class="muted">{{d.resource.moves.length}} moves</p><ul class="move-list"><li v-for="m in [...d.resource.moves].sort((a,b)=>a.name.localeCompare(b.name))" :key="m.name"><a :href="`/moves/${m.name}`">{{human(m.name)}}</a></li></ul></section></template>
</main></template>
